package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class UnitFractionWholeTest {
 @Test public void wholeDistanceUsesScalarInputEvenWhenAnOldFormWasFractional(){Question q=UnitFractionWhole.make(6,853);assertFalse(FractionInput.available(q));assertFalse(FractionInput.defaultFraction(q));Learning.Session s=new Learning.Session();s.question=q;s.answers=new ArrayList<>(List.of(""));s.answerForms=new LinkedHashMap<>();s.answerForms.put(0,new FractionInput.Form(true));assertFalse(FractionInput.form(s,0).fraction);assertEquals("",s.answers.get(0));}
 @Test public void officialExampleUsesPartTimesDenominatorAndIgnoresHiddenKey(){Question q=UnitFractionWhole.make(3,5);q.answers[0]="999";q.expression="999";assertTrue(new Checker().check(q,List.of(),List.of("15")).correct());assertFalse(new Checker().check(q,List.of(),List.of("5/3")).correct());assertFalse(new Checker().check(q,List.of(),List.of("5*3")).correct());HelpPlan help=HelpPlan.forQuestion(q);assertNotNull(help);assertEquals(3,help.size());assertFalse(help.canTransfer());for(int i=0;i<3;i++){assertTrue(help.step(i).accepts(List.of("3","5","15").get(i)));assertEquals("",help.step(i).after);}}
 @Test public void unitsFractionAndBoundsCannotBeReinterpreted(){Question q=UnitFractionWhole.make(12,1000);assertTrue(new Checker().check(q,List.of(),List.of("12000")).correct());assertNull(UnitFractionWhole.read(new Question(UnitFractionWhole.ID,q.prompt.replace("km","m"),"12000","12000")));assertNull(UnitFractionWhole.read(new Question(UnitFractionWhole.ID,q.prompt.replace("1/12","2/12"),"6000","6000")));for(int[] pair:new int[][]{{1,5},{13,5},{3,0},{3,1001}}){try{UnitFractionWhole.make(pair[0],pair[1]);fail();}catch(IllegalArgumentException expected){}}}
 @Test public void normalNaSixHasFreshInverseTasks(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(UnitFractionWhole.ID,6));assertFalse(pack.inGrade(UnitFractionWhole.ID,5));Generator g=new Generator(new Random(282));var limits=GlobalCurriculum.limits(pack.id,UnitFractionWhole.ID,6);List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(UnitFractionWhole.ID,recent,i%2==0,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=UnitFractionWhole.read(q);assertNotNull(v);assertTrue(limits.allows(q));assertTrue(new Checker().check(q,List.of(),List.of(""+(v[0]*v[1]))).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}}
}
